import{_ as i,o as s,c as a,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/grundlagen/einfuehrung-gruppenprozesse-container-zu-prozess.png",d="/bilder/grundlagen/einfuehrung-gruppenprozesse-kategorien.png",u="/bilder/grundlagen/einfuehrung-gruppenprozesse-individualdaten-aendern.png",p="/bilder/grundlagen/einfuehrung-gruppenprozesse-auswahl.png",o="/bilder/grundlagen/status-aktiv.jpg",g="/bilder/grundlagen/einfuehrung-gruppenprozesse-individualdaten-aendern-ausfuehren.png",h="/bilder/grundlagen/sicherheitsabfrage.jpg",c="/bilder/grundlagen/einfuehrung-gruppenprozesse-kontrolle.png",_=JSON.parse('{"title":"Gruppenprozesse sicher anwenden","description":"","frontmatter":{"title":"Gruppenprozesse sicher anwenden","source_pageid":243,"source_revision":4537},"headers":[],"relativePath":"einstieg/grundlagen/einfuehrung-in-die-gruppenprozesse-einfuehrung-in-schild-nrw.md","filePath":"einstieg/grundlagen/einfuehrung-in-die-gruppenprozesse-einfuehrung-in-schild-nrw.md"}'),m={name:"einstieg/grundlagen/einfuehrung-in-die-gruppenprozesse-einfuehrung-in-schild-nrw.md"};function f(b,r,z,w,S,k){return s(),a("div",null,[...r[0]||(r[0]=[t('<h1 id="gruppenprozesse-sicher-anwenden" tabindex="-1">Gruppenprozesse sicher anwenden <a class="header-anchor" href="#gruppenprozesse-sicher-anwenden" aria-label="Permalink to &quot;Gruppenprozesse sicher anwenden&quot;">​</a></h1><p>Ändern Sie Daten für eine zuvor ausgewählte Schülergruppe gemeinsam. Kontrollieren Sie vor dem Start die gefilterte Menge, die Markierungen und die im Gruppenprozess gewählte Bearbeitungsauswahl.</p><h2 id="einfuhrung-in-die-gruppenprozesse" tabindex="-1">Einführung in die Gruppenprozesse <a class="header-anchor" href="#einfuhrung-in-die-gruppenprozesse" aria-label="Permalink to &quot;Einführung in die Gruppenprozesse&quot;">​</a></h2><p><a href="/bilder/grundlagen/einfuehrung-gruppenprozesse-container-zu-prozess.png"><img src="'+l+'" alt="Gruppenprozesse werden für alle Schüler ausgeführt, die im orange hervorgehobenen Container enthalten sind. Hier wird allen Schülern der 05A auf einmal eine bestimmte Fahrschüler-Art zugewiesen." loading="lazy"></a></p><p><em>Gruppenprozesse werden für alle Schüler ausgeführt, die im orange hervorgehobenen Container enthalten sind. Hier wird allen Schülern der 05A auf einmal eine bestimmte Fahrschüler-Art zugewiesen.</em></p><p>Gruppenprozesse erlauben es, Änderungen für eine ausgewählte Gruppe von Schülerinnen und Schülern gleichzeitig durchzuführen.</p><p>Dies erleichtert die Änderung von Daten oder die Berechnung von Abschlüssen, da der notwendige Vorgang nicht für jeden einzelnen Schüler manuell verändert werden muss, sondern für eine ganze Gruppe durchgeführt werden kann.</p><p>Diese Gruppe kann dabei aus allen aktuellen Schülerinnen und Schülern der Schule, einer Jahrgangsstufe oder einer Klasse bestehen. Auch für nach beliebigen anderen Kriterien gefilterten oder beliebig zusammengestellten Schülergruppen können gemeinsam Daten verändert, ergänzt oder gelöscht werden.</p><p>Der <strong>Container</strong> bestimmt die verfügbare Schülergruppe. Prüfen Sie zusätzlich die Auswahl im Gruppenprozess: Ist <strong>nur explizit markierte Schüler</strong> gewählt, werden die gesetzten Markierungen berücksichtigt. Soll nur eine Teilgruppe bearbeitet werden, können Sie zuvor <strong>Filter auf markierte Schüler</strong> anwenden und die verbleibende Liste kontrollieren.</p><p>Prüfen Sie außerdem den <strong>Zielabschnitt</strong> und die Optionen für <strong>Ergänzen, Aktualisieren, Leeren oder Löschen</strong>. Eine leere Eingabe bedeutet nicht in jedem Prozess dasselbe. Die Beschreibung des jeweiligen Prozesses ist maßgeblich.</p><p><a href="/bilder/grundlagen/einfuehrung-gruppenprozesse-kategorien.png"><img src="'+d+'" alt="Die Kategorien, mit denen die Gruppenprozesse geordnet werden." loading="lazy"></a></p><p><em>Die Kategorien, mit denen die Gruppenprozesse geordnet werden.</em></p><p>Öffnen Sie den Karteireiter <strong>Gruppenprozesse</strong>.</p><p>Es stehen folgende Kategorien an Gruppenprozessen zur Verfügung:</p><ul><li><em>Allgemeines</em></li><li><em>Fächer</em></li><li><em>Teilleistungen</em></li><li><em>Noten, Zeugnisvorbereitung</em> und</li><li><em>Lernabschnitte, Versetzung</em>.</li></ul><p>Welche Kategorien angezeigt werden, hängt von der Schulform und der Schülerauswahl ab. Wählen Sie an einer Schule mit gymnasialer Oberstufe ausschließlich Personen der Q2 aus, erscheint zusätzlich <strong>Abitur</strong>.</p><p>Unter diesen Kategorien stehen dann die zugehörigen Gruppenprozesse zur Verfügung.</p><p><a href="/bilder/grundlagen/einfuehrung-gruppenprozesse-individualdaten-aendern.png"><img src="'+u+'" alt="Der Gruppenprozess Individualdaten ändern stellt viele Felder der Schülerdaten zur Verfügung. Über die Reiter oben sind auch noch weitere Daten erreichbar. Hier in Grün wurde der Status hervorgehoben, der im Beispiel dieses Artikels verändert wird. Um die Änderungen bei den Schülern einzutragen, wird auf Ausführen geklickt." loading="lazy"></a></p><p><em>Der Gruppenprozess Individualdaten ändern stellt viele Felder der Schülerdaten zur Verfügung. Über die Reiter oben sind auch noch weitere Daten erreichbar. Hier in Grün wurde der Status hervorgehoben, der im Beispiel dieses Artikels verändert wird. Um die Änderungen bei den Schülern einzutragen, wird auf <code>Ausführen</code> geklickt.</em></p><p>Wählen Sie zum Beispiel den Gruppenprozess <strong>Individualdaten ändern</strong>. Rechts erscheinen die Felder, die Sie ändern können. Die Änderungen gelten für die gesamte ausgewählte Schülergruppe im <strong>Schülercontainer</strong>, also in der Namensliste auf der linken Seite.</p><p>Im Gruppenprozess <em>Individualdaten ändern</em> sind auch noch weitere Felder über die zusätzlichen Reiter zu erreichen.</p><h3 id="beispiel-abandern-des-feldes-status" tabindex="-1">Beispiel: Abändern des Feldes Status <a class="header-anchor" href="#beispiel-abandern-des-feldes-status" aria-label="Permalink to &quot;Beispiel: Abändern des Feldes Status&quot;">​</a></h3><p>Die Schule wurde ins neue Schuljahr hochgeschult. Die Schülerinnen und Schüler der 05A wurden zu diesem Schuljahr neu aufgenommen und haben daher alle den Status <em>Neuaufnahme</em>, dieser soll nun bei allen auf <em>Aktiv</em> umgestellt werden.</p><p><a href="/bilder/grundlagen/einfuehrung-gruppenprozesse-auswahl.png"><img src="'+p+'" alt="Wählen Sie zusätzlich die Neuaufnahme an. Dann stellen Sie die Klasse 05A ein und bestätigen Sie den Filter mit dem Haken." loading="lazy"></a></p><p><em>Wählen Sie zusätzlich die Neuaufnahme an. Dann stellen Sie die Klasse 05A ein und bestätigen Sie den Filter mit dem Haken.</em></p><p>Wählen Sie zuerst die Schüler in der <em>Aktuellen Schülerauswahl</em> aus, die im Container angezeigt werden sollen.</p><ul><li>Es werden auch die Schüler im Status <em>Neuaufnahme</em> durch setzen des Hakens angewählt. Der Haken bei <em>Aktiv</em> bleibt stehen.</li><li>Unter <strong>Klasse</strong> wird die <em>05A</em> im Dropdown-Menü gewählt.</li></ul><p>Wenden Sie den Filter mit einem Klick auf den kleinen Haken rechts neben dem Dropdown-Menü an.</p><p><a href="/bilder/grundlagen/status-aktiv.jpg"><img src="'+o+'" alt="Der Status ist nun auf Aktiv zu stellen." loading="lazy"></a></p><p><em>Der <strong>Status</strong> ist nun auf Aktiv zu stellen.</em></p><p>Zum Abändern des Status&#39; wird der Gruppenprozess <em>Allgemeines</em> ➜ <strong>Individualdaten ändern</strong> ausgewählt.</p><p>Nun wird im Menü im Feld <strong>Status</strong> über das Dropdown-Menü der Eintrag <em>Aktiv</em> ausgewählt.</p><p><a href="/bilder/grundlagen/einfuehrung-gruppenprozesse-individualdaten-aendern-ausfuehren.png"><img src="'+g+'" alt="Klicken Sie auf Ausführen." loading="lazy"></a></p><p><em>Klicken Sie auf <code>Ausführen</code>.</em></p><p>Anschließend muss der Gruppenprozess über den Button <em>Ausführen</em> angestoßen werden.</p><p><a href="/bilder/grundlagen/sicherheitsabfrage.jpg"><img src="'+h+'" alt="Die Sicherheitsabfrage wird mit Ja bestätigt, nachdem noch einmal nachgedacht wurde, ob der Prozess tatsächlich auf der gewählten Schülergruppe ausgeführt werden soll." loading="lazy"></a></p><p><em>Die Sicherheitsabfrage wird mit <code>Ja</code> bestätigt, nachdem noch einmal nachgedacht wurde, ob der Prozess tatsächlich auf der gewählten Schülergruppe ausgeführt werden soll.</em></p><p>Wird die folgende Sicherheitsabfrage <em>Daten bei allen ausgewählten Schülern ändern</em> bejaht, ist der Gruppenprozess abgeschlossen.</p><p><a href="/bilder/grundlagen/einfuehrung-gruppenprozesse-kontrolle.png"><img src="'+c+'" alt="Der Status wurde bei der kompletten Gruppe geändert." loading="lazy"></a></p><p><em>Der Status wurde bei der kompletten Gruppe geändert.</em></p><p>Die Kontrolle im Reiter <em>Individualdaten I</em> einer Schülerin zeigt, dass der Prozess erfolgreich durchgeführt wurde.</p>',41),e("div",{"data-hint-kind":"right",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"right","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"m8 12 3 3 5-6"})]),n("Richtig – Fertig")]),e("p",null,[n("Anstelle dass bei jedem einzelnen Schüler der "),e("strong",null,"Status"),n(" verändert werden musste, wurde diese Operation nun schnell für die ganzen Gruppe erledigt.")])],-1),e("hr",null,null,-1),e("h2",{id:"videotutorials",tabindex:"-1"},[n("Videotutorials "),e("a",{class:"header-anchor",href:"#videotutorials","aria-label":'Permalink to "Videotutorials"'},"​")],-1),e("h3",{id:"grundlagen-zum-thema-gruppenprozesse",tabindex:"-1"},[n("Grundlagen zum Thema Gruppenprozesse "),e("a",{class:"header-anchor",href:"#grundlagen-zum-thema-gruppenprozesse","aria-label":'Permalink to "Grundlagen zum Thema Gruppenprozesse"'},"​")],-1),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/mYl_uzhFLkA?",frameborder:"0",allowfullscreen:""},null,-1),e("h3",{id:"abandern-des-feldes-status",tabindex:"-1"},[n("Abändern des Feldes Status "),e("a",{class:"header-anchor",href:"#abandern-des-feldes-status","aria-label":'Permalink to "Abändern des Feldes Status"'},"​")],-1),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/9retUdwaZhs?",frameborder:"0",allowfullscreen:""},null,-1),e("h3",{id:"klasse-per-gruppenprozess-zuweisen",tabindex:"-1"},[n("Klasse per Gruppenprozess zuweisen "),e("a",{class:"header-anchor",href:"#klasse-per-gruppenprozess-zuweisen","aria-label":'Permalink to "Klasse per Gruppenprozess zuweisen"'},"​")],-1),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/BLH3x_G72JU?",frameborder:"0",allowfullscreen:""},null,-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Einf%C3%BChrung_in_die_Gruppenprozesse_(Einf%C3%BChrung_in_SchILD-NRW)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 4537.")],-1)])])}const G=i(m,[["render",f]]);export{_ as __pageData,G as default};
